 {stage==='lunch-food'&&<section className="lunch-prompt" key="food"><h2 className="lunch-message">What are you craving?</h2><div className="lunch-options" aria-label="Food choices">{['Rice & bowls','Noodles','Something light','A quick bite','Surprise me'].map(food=><button key={food} onClick={()=>chooseLunchFood(food)}>{food}</button>)}<button className="write-option" onClick={writeLunchAnswer}><Pencil1Icon/>Something else</button></div></section>}
 {stage==='lunch-size'&&<section className="lunch-prompt" key="size"><h2 className="lunch-message">How many at the table?</h2><div className="lunch-options lunch-size-options" aria-label="Table size choices">{['2','3','4','More'].map(size=><button key={size} onClick={()=>chooseLunchSize(size)}>{size==='More'?'More':size+' people'}</button>)}</div></section>}
 {stage==='lunch-time'&&<section className="lunch-prompt" key="time"><h2 className="lunch-message">What time works for you?</h2><div className="lunch-options" aria-label={`${meal} time choices`}>{(meal==='Dinner'?['17:30','18:00','18:30','19:00']:['11:30','12:00','12:30','13:00']).map(time=><button key={time} onClick={()=>chooseLunchTime(time)}>{time}</button>)}<button className="write-option" onClick={writeLunchAnswer}><Pencil1Icon/>Another time</button></div></section>}
