// October Figma sync: product UI stays inside the shared mobile runtime.
function AvatarSetup({stage,setStage,photo,setPhoto,onContinue}:{stage:'empty'|'photo'|'generating'|'ready';setStage:(s:'empty'|'photo'|'generating'|'ready')=>void;photo:string;setPhoto:(s:string)=>void;onContinue:()=>void}){
 const fileRef=useRef<HTMLInputElement>(null),timer=useRef<ReturnType<typeof setInterval>|null>(null);const [progress,setProgress]=useState(0),[notice,setNotice]=useState('');const {bottomInset}=useKeyboardInsets();
 useEffect(()=>{if(stage!=='generating')return;setProgress(10);timer.current=setInterval(()=>setProgress(p=>Math.min(100,p+15)),320);return()=>{if(timer.current)clearInterval(timer.current)}},[stage]);
 useEffect(()=>{if(progress===100&&stage==='generating'){setPhoto('/figma/cartoon.png');setStage('ready')}},[progress,stage,setPhoto,setStage]);
 function sample(){setNotice('Demo photo · fictional person');setPhoto('/figma/portrait.png');setStage('photo')}
 return <><div className="avatar-capture-card"><div className="avatar-capture-frame">{stage==='empty'?<div className="avatar-empty"><img src="/figma/avatar-empty.svg" alt=""/><strong>Start with a photo of you</strong><small>Take a photo or choose one below.</small></div>:<img src={photo} alt={stage==='ready'?'Cartoon avatar':'Selected profile photo'}/>} {stage==='generating'&&<div className="avatar-generating" role="status" aria-label={`Creating demo avatar ${progress}%`}>{progress}%</div>}</div></div>{notice&&<p className="sync-meta sync-center">{notice}</p>}<input ref={fileRef} className="onboarding-file" type="file" accept="image/*" onChange={e=>{const file=e.target.files?.[0];if(file){setPhoto(URL.createObjectURL(file));setStage('photo');setNotice('Your photo is kept locally. AI generation uses the sample photo in this demo.')}}}/><FixedActions>{stage==='empty'?<><Button onClick={sample}>Take photo</Button><Button secondary onClick={()=>fileRef.current?.click()}>Choose from photos</Button></>:stage==='ready'?<><Button onClick={onContinue}>Use this avatar</Button><Button secondary onClick={()=>{setPhoto('');setStage('empty')}}>Try another photo</Button></>:<><Button disabled={stage==='generating'} onClick={()=>{if(photo.startsWith('blob:')){setNotice('AI generation is mocked for the sample portrait. You can keep your photo, or try the sample.');return}setStage('generating')}}>{stage==='generating'?'Please wait':'Create my AI avatar'}</Button><Button secondary onClick={()=>{setStage('photo');onContinue()}}>Keep my real photo</Button>{photo.startsWith('blob:')&&<button className="text-button" onClick={sample}>Try the demo portrait</button>}</>}</FixedActions></>
}
const prepSuggestions=[
 {title:'A path into product',detail:'The move from design into product.',ask:'Was there a moment when product started to feel right?',share:'A moment when my own work felt too narrow.'},
 {title:'Design skills in product',detail:'The strengths that carry over.',ask:'Where did your design background make a difference?',share:'A design strength I enjoy using, and where I could use it next.'},
 {title:'A first step in my role',detail:'A small experiment I could try.',ask:'What small task would you try first in my position?',share:'Where I want to get involved and what holds me back.'}
];
function CoffeePreparation({person,subject,saved,purpose,onSave,onDone,step,setStep,notes}:{person:string;subject:string;saved:string[];purpose:string;onSave:(p:string,n:string[],id:number|null)=>void;onDone:()=>void;step:number;setStep:(n:number)=>void;notes:{id:number;purpose:string;questions:string[]}[]}){
 const [noteId,setNoteId]=useState<number|null>(null),[goal,setGoal]=useState(purpose||'Find a small way to try product work in my current role.'),[purposeChoice,setPurposeChoice]=useState(1),[selected,setSelected]=useState(saved.length?saved.slice(0,3).map((_,i)=>i):[0,1,2]),[expanded,setExpanded]=useState(1),[editing,setEditing]=useState(-1),[questions,setQuestions]=useState(saved.length?saved:prepSuggestions.map(p=>p.ask)),[variant,setVariant]=useState(false);const keyboard=useKeyboard(),{bottomInset}=useKeyboardInsets();
 const titles=variant?['The turning point','Learning on the job','A small next step']:prepSuggestions.map(p=>p.title);
 function refresh(){setVariant(v=>!v);setQuestions(variant?prepSuggestions.map(p=>p.ask):['What made you want to try something different?','What did you learn by doing, rather than studying?','What is one experiment I can try next week?'])}
 return <section className="sync-prep sync-stack">{step>0&&step<4&&<nav className="sync-steps" aria-label="Preparation steps">{['Purpose','Topics','Notes'].map((s,i)=><button key={s} className={step===i+1?'active':''} disabled={i+1>step} onClick={()=>setStep(i+1)}>{i+1} {s}</button>)}</nav>}{step===0||step===4?<><h1>Your notes</h1>{saved.length?<><p><LockClosedIcon/> Only you can see these</p>{(notes.length?notes:[{id:0,purpose:purpose||goal,questions:saved}]).map(note=><button className="sync-card sync-notes-library" key={note.id} onClick={()=>{setNoteId(note.id||null);setGoal(note.purpose);setQuestions(note.questions);setSelected(note.questions.map((_,i)=>i));setStep(3)}}><h1>{note.purpose}</h1>{note.questions.map((q,i)=><div key={q+i}><small>{String(i+1).padStart(2,'0')}</small><span>{titles[i]||q}</span></div>)}<ArrowRightIcon/></button>)}</>:<div className="sync-notes-empty"><div className="sync-paper"><Pencil1Icon/><i/><i/><i/></div><h2>Your first note starts here</h2><p>Prepare a few things you’d like to talk<br/>about with {person.split(' ')[0]}.</p></div>}</>:step===1?<><h1>What would you like to take away?</h1><div className="sync-purpose-options">{['Explore a career move','Get practical advice','Learn from experience'].map((g,i)=><article className={'sync-card sync-purpose '+(purposeChoice===i?'selected':'')} key={g}><button onClick={()=>{setPurposeChoice(i);setGoal(['Explore what a move into product could look like.','Find a small way to try product work in my current role.','Learn from the experiences that shaped your work.'][i])}}><span className="sync-radio">{purposeChoice===i&&<i/>}</span><strong>{g}</strong></button>{purposeChoice===i&&<label>I’d like to talk about…<KeyboardTextarea aria-label="Chat purpose" value={goal} onChange={e=>setGoal(e.target.value)} onBlur={()=>keyboard.hide()} rows={2}/></label>}</article>)}</div></>:step===2?<><div><h1>Explore your topics</h1><p className="sync-meta">{selected.length} of 3 topics selected</p></div>{prepSuggestions.map((t,i)=><article className="sync-card sync-topic" key={i}><div className="row"><button className="sync-checkbox" aria-label={`Select ${titles[i]}`} aria-pressed={selected.includes(i)} onClick={()=>setSelected(a=>a.includes(i)?a.filter(n=>n!==i):[...a,i])}>{selected.includes(i)&&<CheckIcon/>}</button><button className="sync-topic-title" aria-expanded={expanded===i} onClick={()=>setExpanded(expanded===i?-1:i)}><strong>{i===0&&!variant?person.split(' ')[0]+"’s path into product":titles[i]}</strong><small>{t.detail}</small></button><button aria-label={`Expand ${titles[i]}`} className="icon-button" onClick={()=>setExpanded(expanded===i?-1:i)}><ChevronRightIcon/></button></div>{expanded===i&&<div className="sync-tint">{editing===i?<KeyboardTextarea aria-label="Edit topic question" value={questions[i]} onChange={e=>setQuestions(q=>q.map((x,j)=>j===i?e.target.value:x))} onBlur={()=>{keyboard.hide();setEditing(-1)}} rows={3}/>:<p>{questions[i]}</p>}<button className="chip" onClick={()=>setEditing(i)}><Pencil1Icon/> Edit</button></div>}</article>)}<button className="text-button" onClick={refresh}><MixIcon/>Try three new topics</button></>:<><h1>Your chat notes</h1><p className="sync-meta">“{goal}”</p><article className="sync-card"><small>Start here</small><p>“I’m curious about {subject.toLowerCase()}. How did it begin for you?”</p></article>{selected.map((i,n)=><article className="sync-card sync-note" key={i}><h2><small>{String(n+1).padStart(2,'0')}</small> {titles[i]}</h2><p className="sync-meta">{prepSuggestions[i].detail}</p><small>Ask</small><h3>“{questions[i]}”</h3><small>Share</small><p>{prepSuggestions[i].share}</p></article>)}<div><strong>Before you finish</strong><p>“One thing I’ll take from today is…”</p></div></>}<FixedActions><Button disabled={step===1&&!goal.trim()||step===2&&(!selected.length||selected.some(i=>!questions[i]?.trim()))} onClick={()=>{keyboard.hide();if(step===0||step===4){setNoteId(null);setQuestions(prepSuggestions.map(p=>p.ask));setSelected([0,1,2]);setStep(1)}else if(step<3)setStep(step+1);else{onSave(goal,selected.map(i=>questions[i]),noteId);setStep(4)}}}>{['Create a note','Explore my topics','Build my notes','Save my note','Create a new note'][step]}<ArrowRightIcon/></Button></FixedActions></section>
}
function CoffeeCall({person,notes,onEnd}:{person:string;notes:string[];onEnd:()=>void}){
 const [joined,setJoined]=useState(false),[mic,setMic]=useState(true),[camera,setCamera]=useState(true),[showNotes,setShowNotes]=useState(false),[seconds,setSeconds]=useState(0);useEffect(()=>{if(!joined)return;const t=setInterval(()=>setSeconds(s=>s+1),1000);return()=>clearInterval(t)},[joined]);
 return <section className="sync-call sync-stack"><div className="row between"><div><h2>{person}</h2><small>{joined?`Demo call · ${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`:'Ready for your coffee chat?'}</small></div>{joined&&<button className="sync-hangup" aria-label="End call" onClick={onEnd}><img src="/figma/phone.svg" alt=""/></button>}</div><div className="sync-video"><img className="sync-video-person" src={joined?'/figma/video-person.png':'/figma/video-self.png'} alt={joined?`${person} demo video`:'Your video preview'}/>{!camera&&<div className="sync-camera-off"><PersonIcon/>Camera off</div>}{joined&&<img className="sync-self-video" src="/figma/video-self.png" alt="Your preview"/>}<span className="sync-video-name">{joined?person:'You'}</span></div><div className="sync-call-controls">{[['microphone',mic?'Mic':'Muted',()=>setMic(!mic)],['video',camera?'Camera':'Off',()=>setCamera(!camera)],['notebook','Notes',()=>setShowNotes(true)]].map(([icon,label,action])=><button key={icon as string} onClick={action as ()=>void}><span><img src={`/figma/${icon}.svg`} alt=""/></span>{label as string}</button>)}</div>{!joined&&<><Button onClick={()=>setJoined(true)}>Join chat</Button><p className="sync-meta sync-center">Local call preview · camera and microphone are not recorded.</p></>}<BottomSheet open={showNotes} onOpenChange={setShowNotes} title="Your chat notes" snap={.72}><button className="sync-sheet-close" aria-label="Close notes" onClick={()=>setShowNotes(false)}><Cross1Icon/></button><MobileScroll className="sync-sheet-scroll"><div className="sync-stack">{notes.length?notes.map((q,i)=><article className="sync-card" key={i}><small>Topic {i+1}</small><h3>{q}</h3></article>):<p>You haven’t saved any notes yet. You can still follow your curiosity.</p>}<Button secondary onClick={()=>setShowNotes(false)}>Back to the chat</Button></div></MobileScroll></BottomSheet></section>
}
function CommunityHub({plans,openPlan,tab,setTab,onToast,hub,setHub,route,setRoute,selfName}:{plans:Plan[];openPlan:(id:number)=>void;tab:string;setTab:(t:string)=>void;onToast:(s:string)=>void;route:string;setRoute:(s:string)=>void;selfName:string;hub:{friends:string[];pending:string[];messages:Record<string,string[]>};setHub:React.Dispatch<React.SetStateAction<{friends:string[];pending:string[];messages:Record<string,string[]>}>>}){
 const [search,setSearch]=useState(''),[sheet,setSheet]=useState(''),[phone,setPhone]=useState(''),[found,setFound]=useState(false),[message,setMessage]=useState('');const keyboard=useKeyboard();const person=route.startsWith('person:')?route.slice(7):'';const setPerson=(s:string)=>setRoute(s?'person:'+s:'');const {friends,pending,messages}=hub;const setFriends=(fn:(a:string[])=>string[])=>setHub(h=>({...h,friends:fn(h.friends)}));const setPending=(fn:(a:string[])=>string[])=>setHub(h=>({...h,pending:fn(h.pending)}));const setMessages=(fn:(a:Record<string,string[]>)=>Record<string,string[]>)=>setHub(h=>({...h,messages:fn(h.messages)}));
 const people=tab==='Recommend'?['Sophie Wu','Daniel Kim']:tab==='Friends'?[...friends,...['Mia Chen','Noah Yu'].filter(n=>!friends.includes(n))]:['Zoe Lin','Mia Chen','Emma Park'];
 function request(n:string){setPending(p=>[...p,n]);onToast('Friend request added in this demo.')}
 return <section className="sync-community sync-stack">{route==='qr'?<><div className="sync-qr-person"><Avatar name={selfName.split(' ').map(n=>n[0]).join('').slice(0,2)}/><h1>{selfName}</h1><small>Product Designer · ArtTech</small></div><div className="sync-qr-card"><img src="/figma/demo-qr.svg" alt="Demo Overlap QR code"/></div><p className="sync-meta sync-center">Ask a friend to scan your code.<br/>You choose which requests to accept.</p><FixedActions><Button onClick={()=>setRoute('scan')}>Scan a friend’s code</Button></FixedActions></>:route==='scan'?<><p className="sync-center">Place an Overlap QR code<br/>inside the frame.</p><div className="sync-scan-frame"/><button className="sync-card sync-conversation" onClick={()=>setPerson('Mia Chen')}><Avatar name="MC"/><div><strong>Mia Chen</strong><small>Code recognized · View profile</small></div><ChevronRightIcon/></button><p className="sync-meta sync-center">Demo scan · Review their profile before adding them.</p></>:<>{!person&&<nav className="sync-tabs">{['Messages','Friends','Recommend'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>{setPerson('');setTab(t)}}>{t}</button>)}</nav>}{person?<><button className="text-button" onClick={()=>setPerson('')}><ArrowLeftIcon/>Back to {tab.toLowerCase()}</button><article className="sync-card"><div className="sync-person"><Avatar name={person.split(' ').map(n=>n[0]).join('')}/><div><h2>{person}</h2><small>Design · Campus A</small></div></div><p>Good coffee, quiet walks and a little curiosity.</p><div className="tags"><span>Photography</span><span>Design</span><span>Walks</span></div>{!friends.includes(person)&&<Button disabled={pending.includes(person)} onClick={()=>request(person)}>{pending.includes(person)?'Request sent':'Add friend'}</Button>}</article>{tab==='Messages'||friends.includes(person)?<><div className="sync-stack sync-messages">{(messages[person]||['Good to see you here!']).map((m,i)=><div className={i===0?'assistant-bubble':'user-bubble'} key={i}>{m}</div>)}</div><form className="sync-inline-composer" onSubmit={e=>{e.preventDefault();if(!message.trim())return;setMessages(all=>({...all,[person]:[...(all[person]||['Good to see you here!']),message.trim()]}));setMessage('');keyboard.hide()}}><KeyboardInput aria-label={`Message ${person}`} placeholder="Say hello…" value={message} onChange={e=>setMessage(e.target.value)}/><button className="send" disabled={!message.trim()} aria-label="Send private message"><ArrowUpIcon/></button></form></>:<p className="sync-meta">Send a request to start a conversation.</p>}</>:<><div className="sync-search"><MagnifyingGlassIcon/><KeyboardInput aria-label="Search people" placeholder="Search people" value={search} onChange={e=>setSearch(e.target.value)}/><button aria-label="Add friends" onClick={()=>{keyboard.hide();setSheet('Add friends')}}><PlusIcon/></button></div>{tab==='Friends'&&<button className="sync-card row between" onClick={()=>setSheet('Friend requests')}><strong>Friend requests</strong><span className="tag">1</span><ChevronRightIcon/></button>}{tab==='Messages'&&plans.map(p=><button className="sync-card sync-conversation" key={p.id} onClick={()=>openPlan(p.id)}><Avatar name={p.people.split(' ').map(n=>n[0]).join('').slice(0,2)}/><div><strong>{p.people}</strong><small>{p.messages.at(-1)?.text||p.title}</small></div><ChevronRightIcon/></button>)}<div className="sync-card sync-list">{people.filter(n=>n.toLowerCase().includes(search.toLowerCase())).map((n,i)=><button key={n} onClick={()=>setPerson(n)}><Avatar name={n.split(' ').map(x=>x[0]).join('')}/><div><strong>{n}</strong><small>{tab==='Messages'?['I found the example I mentioned.','See you at the café!','Thanks for a lovely afternoon.'][i%3]:friends.includes(n)?'Friend · Campus A':'A little common ground'}</small></div><ChevronRightIcon/></button>)}</div></>}</>}<BottomSheet open={!!sheet} onOpenChange={o=>!o&&setSheet('')} title={sheet} snap={.64}><button className="sync-sheet-close" aria-label="Close sheet" onClick={()=>setSheet('')}><Cross1Icon/></button><MobileScroll className="sync-sheet-scroll"><div className="sync-stack">{sheet==='Add friends'?<><Button secondary onClick={()=>{setFound(false);setSheet('Phone number')}}>Find by phone number</Button><Button secondary onClick={()=>{setSheet('');setRoute('scan')}}>Scan QR code</Button><Button secondary onClick={()=>{setSheet('');setRoute('qr')}}>My QR code</Button></>:sheet==='Phone number'?<><label>Phone number<KeyboardInput aria-label="Friend phone number" inputMode="tel" value={phone} onChange={e=>{setPhone(e.target.value);setFound(false)}} placeholder="Enter a phone number"/></label><Button disabled={!/^\+?[\d\s-]{7,18}$/.test(phone)} onClick={()=>{keyboard.hide();setFound(true)}}>Find person</Button>{found&&<article className="sync-card"><h2>Mia Chen</h2><p className="sync-meta">Sample search result</p><Button disabled={pending.includes('Mia Chen')} onClick={()=>request('Mia Chen')}>{pending.includes('Mia Chen')?'Request sent':'Add friend'}</Button></article>}</>:sheet==='Friend requests'?<article className="sync-card"><h2>Leo Chen</h2><p>Would like to connect with you.</p><Button disabled={friends.includes('Leo Chen')} onClick={()=>{setFriends(f=>[...f,'Leo Chen']);onToast('Leo is now in your demo friends.')}}>{friends.includes('Leo Chen')?'Added':'Accept request'}</Button></article>:<><div className="sync-qr-placeholder"><PersonIcon/><strong>{sheet==='My QR code'?'Your Overlap code':'Place an Overlap QR code inside the frame'}</strong></div><p className="sync-meta">QR scanning is simulated in this local prototype.</p><Button onClick={()=>{setSheet('');setPerson('Mia Chen')}}>{sheet==='My QR code'?'Preview shared profile':'Preview recognized profile'}</Button></>}</div></MobileScroll></BottomSheet></section>
}

function FixedActions({children}:{children:ReactNode}){const {screenRef}=useScreenPortal(),{bottomInset}=useKeyboardInsets();const [target,setTarget]=useState<Element|null>(null);useLayoutEffect(()=>setTarget(screenRef.current?.querySelector('.overlap-app')||null),[screenRef]);return target?createPortal(<div className="sync-fixed-actions" style={{bottom:bottomInset+12}}>{children}</div>,target):null}

type ProfileDraft={about:string;interests:string[];visibility:string;directInvites:boolean;shareCampus:boolean};
function ProfileEditor({name,role,company,photo,onSave,...initial}:{name:string;role:string;company:string;photo:string;onSave:(v:ProfileDraft)=>void}&ProfileDraft){
 const [draft,setDraft]=useState(initial),[tag,setTag]=useState('');const keyboard=useKeyboard();
 return <section className="sync-stack sync-profile-editor"><h1>Make it yours.</h1><p className="sync-meta">A few words to help people get to know you.</p><article className="sync-card"><div className="sync-person">{photo?<img src={photo} alt="Your avatar"/>:<Avatar name={name.split(' ').map(x=>x[0]).join('').slice(0,2)}/>}<div><strong>{name}</strong><small>{role} · {company}</small></div></div><KeyboardTextarea aria-label="About yourself" placeholder="A little about you…" value={draft.about} onChange={e=>setDraft(d=>({...d,about:e.target.value}))} onBlur={()=>keyboard.hide()} rows={4}/><small>My social style</small><div className="chips">{draft.interests.map(t=><button className="chip" aria-label={'Remove '+t} key={t} onClick={()=>setDraft(d=>({...d,interests:d.interests.filter(x=>x!==t)}))}>{t} ×</button>)}</div><div className="sync-inline-composer"><KeyboardInput aria-label="Add your own tag" placeholder="Add your own tag" value={tag} onChange={e=>setTag(e.target.value)}/><Button secondary disabled={!tag.trim()} onClick={()=>{setDraft(d=>({...d,interests:[...new Set([...d.interests,tag.trim()])]}));setTag('');keyboard.hide()}}>Add</Button></div></article><article className="sync-card"><label>Who can discover me?<Chips options={['Company','Connections','Hidden']} value={draft.visibility} onChange={visibility=>setDraft(d=>({...d,visibility}))}/></label>{(['directInvites','shareCampus'] as const).map((field,i)=><button className="sync-setting-row" role="switch" aria-checked={draft[field]} key={field} onClick={()=>setDraft(d=>({...d,[field]:!d[field]}))}><div><strong>{i?'Share campus only':'Direct invitations'}</strong><small>{i?'Exact location appears after you accept.':'People who can discover you may invite you.'}</small></div><span className={'toggle '+(draft[field]?'on':'')}><span/></span></button>)}<p className="sync-meta">✓ Your answers and matching preferences stay private.</p></article><FixedActions><Button onClick={()=>{keyboard.hide();onSave(draft)}}>Save changes</Button></FixedActions></section>
}
